    layer_time = [0] * min_count

    for col in cols:
        col.sort()
        for r, (y, idx) in enumerate(col):
            rank[idx] = r
            if r < min_count:
                if y > layer_time[r]:
                    layer_time[r] = y

    for col in cols:
        for r, (_, idx) in enumerate(col):
            if r < min_count:
                disappear[idx] = layer_time[r]

    Q = int(input())
    ans = []
    for _ in range(Q):
